head.script:
scwin.screenId = "jldfil05020";

///////// 1. 변수 및 선언 영역 /////////

// as-is 공용 상수 — 셸이 js/elw.js 를 싣지 않아 화면에 선언한다(KRX 합의 대상).
scwin.LD_MKT_TP_CD = '1';

scwin.BZ_NEWLST = 1;

scwin.BZ_ADDPRE = 2;

scwin.BZ_ADDLST = 3;

scwin.CD_NEWLST = '003';

scwin.form = null;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  ==  2 || (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  ==  3); } }, { id: "btn_Register_2", fn: function(){ return ((dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  4); } }, { id: "btn_ElwSub", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  4); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_nm", fn: function () { return String(dlt_readDataVOArrayUser.getCellData(0, "nm")); } },
        { childId: "ipt_telNo", fn: function () { return String(dlt_readDataVOArrayUser.getCellData(0, "telNo")); } },
        { childId: "ipt_faxNo", fn: function () { return String(dlt_readDataVOArrayUser.getCellData(0, "faxNo")); } },
        { childId: "ipt_email", fn: function () { return String(dlt_readDataVOArrayUser.getCellData(0, "email")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.form = (document.ElwForm || { elements: [] });
        $c.util.getComponent("dma_RegisterReq").set("bzCd", scwin.BZ_NEWLST);
        $c.util.getComponent("dma_RegisterReq").set("listBzTpCd", scwin.CD_NEWLST);
        $c.util.getComponent("dma_RegisterReq").set("spotIsuTrdMktTpCd", scwin.LD_MKT_TP_CD);
        /* 수동 전환 필요: transTbl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        await (async () => { const m = $c.util.getComponent("dma_readDataVO"); const v = (m && m.get) ? m.get("resultMsg") : ""; if (v) { await $c.win.alert(String(v)); } })();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05020.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05020.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Register_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Register_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Register_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.register()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05020.btn_Register_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Register_2_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Register_2_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Register_2_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.register()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05020.btn_Register_2_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_ElwPageSearch_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_ElwPageSearch_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_ElwPageSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.elwPageSearch()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05020.btn_ElwPageSearch_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_ElwSub_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_ElwSub_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_ElwSub_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.elwSub()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05020.btn_ElwSub_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05020.tx_fn_Register" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_loadListReq",
        target: "dlt_readDataVOArrayUser=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05020.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.isPossibleSave()) {
        return;
    }
    if (!fn_UserCheckValues()) {
        return;
    }
    if (!$c.lc.fn_isProcess('I')) {
        return;
    }
    scwin.form.action = '/list/elw.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerElw');
    await scwin.tx_fn_Register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setInitData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setInitData = function () {
    /* sdd-asis-lifecycle:begin fn_SetInitData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('ipt_nm').getValue() == null ? '' : String($c.util.getComponent('ipt_nm').getValue())) === '') {
        $c.util.getComponent('ipt_nm').setValue("wookijun");
    }
    if (($c.util.getComponent('ipt_telNo').getValue() == null ? '' : String($c.util.getComponent('ipt_telNo').getValue())) === '') {
        $c.util.getComponent('ipt_telNo').setValue("02-767-7668");
    }
    if (($c.util.getComponent('ipt_faxNo').getValue() == null ? '' : String($c.util.getComponent('ipt_faxNo').getValue())) === '') {
        $c.util.getComponent('ipt_faxNo').setValue("22");
    }
    if (($c.util.getComponent('ipt_email').getValue() == null ? '' : String($c.util.getComponent('ipt_email').getValue())) === '') {
        $c.util.getComponent('ipt_email').setValue("ddddd");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.elwPageSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.elwPageSearch = async function () {
    /* sdd-asis-lifecycle:begin fn_ElwPageSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if( scwin.form.isuNm != null ) {
        scwin.form.isuNm.value  = "" ;
    }
    scwin.form.action       = '/list/elwPage.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'elwPageSearch');
    await moveUrl('/list/elwPage.do', {});

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.elwSub
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.elwSub = async function () {
    /* sdd-asis-lifecycle:begin fn_ElwSub — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    //	alert("fn_ElwSub  ==  " + bzProcsNo);
    if(isNotAdmin()){
        if( ($c.util.getComponent("dma_RegisterReq").get("billLstSaveStatCd")) != 4 ) {
            await $c.win.alert("신청인정보  페이지까지 입력을 하셔야만 제출 하실수 있습니다.");
            return ;
        }

        //-- 기준가격,행사가격 데이타 검증 -->
        if(!fn_chkSaveElwPrc() ) return  ;

        $c.util.getComponent("dma_RegisterReq").set("listProcsStatCd", CD_STAT_FIN);  /* 상장처리상태코드 */

        if (! $c.lc.fn_isProcess('S') )  return ;

        scwin.form.action = '/list/elwPage.do';
        $c.util.getComponent('dma_RegisterReq').set('method', 'elwPageSub');
        await moveUrl('/list/elwPage.do', {});
    }

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isPossibleSave
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.isPossibleSave = async function () {
    /* sdd-asis-lifecycle:begin fn_isPossibleSave — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    isNotAdmin();

    // BZ_ADDPRE 중  '00' , '02' 만 저장가능
    // 2012/08/08 KBoY 반송시 해당탭으로 이동하기 위해 반송시 기존꺼 02로 돌리고 03으로 하나를 카피 뜨기 때문에 02로 올 일이 없다.
    if( $c.util.getComponent("dma_RegisterReq").get("bzCd") === scwin.BZ_ADDPRE || $c.util.getComponent("dma_RegisterReq").get("bzCd") === scwin.BZ_ADDLST) {
        if( $c.util.getComponent("dma_RegisterReq").get("listProcsStatCd") !== "" && $c.util.getComponent("dma_RegisterReq").get("listProcsStatCd") !== CD_STAT_ING && $c.util.getComponent("dma_RegisterReq").get("listProcsStatCd") !== '03' ) {

            await $c.win.alert("\n 해당 종목이 처리중입니다.       \n\n 목록에서 상태를 확인하세요.") ;
            return  false;
        }
    }

    // 반송된 업무처리일경우는 첫페이지에서만 저장이 가능 2012-07-31 KBoY 03으로 오기 때문에 앞으로 여기 올일 없음.
    if( $c.util.getComponent("dma_RegisterReq").get("listProcsStatCd") === CD_STAT_REJ ) {

        if(($c.util.getComponent("dma_RegisterReq").get("nowPage")) == 1 ) {

            $c.util.getComponent("dma_RegisterReq").set("bzProcsNo", "");
            $c.util.getComponent("dma_RegisterReq").set("transKind", INSERT);
            $c.util.getComponent("dma_RegisterReq").set("listProcsStatCd", CD_STAT_ING);  /* 상장처리상태코드 */

            return true ;

        } else {
            await $c.win.alert("\n 현재 텝에서는 저장을 할수 없습니다. \n\n 증권발행개요 탭으로 이동후, 저장을 하세요") ;
            return false ;
        }
    }

    //3단계(파일첨부) 입력안해도 다음단계로 이동가능하도록 수정 (2010-02-01)
    if($c.util.getComponent("dma_RegisterReq").get("billLstSaveStatCd") < 2) {
        if( ($c.util.getComponent("dma_RegisterReq").get("nowPage")) > (($c.util.getComponent("dma_RegisterReq").get("billLstSaveStatCd")) + 1)) {
            await $c.win.alert("\n 현재 텝에서는 저장을 할수 없습니다. \n\n 탭별로 작성후 저장하셔야 합니다..");
            return false ;
        }
    }
    //2012-07-31 KBoY 다시 저장할때 prelistBizImpl doChangeListPorcsStatCd()에서 '03'받아다 00으로 강제 세팅함...
    if( $c.util.getComponent("dma_RegisterReq").get("listProcsStatCd") !== '03' ) {
        $c.util.getComponent("dma_RegisterReq").set("listProcsStatCd", CD_STAT_ING);  /* 상장처리상태코드 */
    }

    //viewFormNameAndData();
    if( $c.util.getComponent("dma_RegisterReq").get("bzProcsNo") === "" )
    $c.util.getComponent("dma_RegisterReq").set("transKind", INSERT);
    else
    $c.util.getComponent("dma_RegisterReq").set("transKind", UPDATE);

    return true ;

    /* sdd-asis-lifecycle:end */
};
